  CollectionHall_147987_Desc = {
    Text = "Di atas hamparan yang gersang, binatang-binatang bermata garang berkeliaran, semuanya mencari kesempatan — kesempatan untuk menancapkan taring ke leher dan merobek lawan hingga hancur sepenuhnya."
