  CollectionHall_48635_Title = {Text = "Czort"},
  CollectionHall_48636_Desc = {
    Text = "<Title:Ringkasan>\nSalah satu dari tiga pendiri, bersama dengan Wald Phillips dan Keralc, mendirikan cikal bakal Universitas Mythag — Perguruan Tinggi Mythag.\nAdalah \"Bangun\" pertama, serta penyedia teknologi Bangun.\nSelalu menjaga Kolam Hitam, sangat sedikit orang yang pernah melihat wajahnya, menjadi salah satu rahasia terbesar Universitas Mythag.\n\"Shh… jangan mencoba menguji @2mu.\""
