  CollectionHall_51374_Desc = {
    Text = [[
<Title:Ringkasan>
Profesor Universitas Mythag, aktivis sosial, bangsawan.
Dulu adalah playboy yang boros dan melakukan beberapa pelanggaran kecil tanpa konsekuensi serius, dikenal di kalangan hitam dan putih.
Keluarganya kemudian dibantai oleh para pengikut sekte jahat, dan dia menjadi satu-satunya penyintas. Apa yang terjadi setelah itu hanya bisa dijelaskan olehnya sendiri.
Meskipun dia ayah angkat Ramona, dia tetap bungkam tentang asal-usul Ramona.
Semua mata pelajarannya gagal saat muda, namun entah bagaimana berhasil menjadi profesor di Universitas Mythag.
Dia berwatak bebas dan tidak terikat, namun tak pernah ada gosip tentang hubungan dengan wanita atau pria.
Singkatnya, dia adalah seseorang yang penuh dengan kontradiksi.]]
  },
  CollectionHall_51374_LockTip = {
    Text = "Membuka setelah menyelesaikan prolog"
  },
  CollectionHall_51374_Title = {Text = "Dexter"},
  CollectionHall_51375_Desc = {
    Text = "<Title:Ikhtisar>\nAnak angkat Dexter, mitra penyelidikan paling dipercaya oleh karakter utama.\nSejak kecil sering berada di kelas-kelas berbagai departemen di akademi, memiliki pemahaman yang cukup tentang fenomena-d, pembangun, dan pengetahuan terkait.\n\nMeskipun Ramona pernah merindukan \"orang tua kandung\" saat masih muda, di bawah perawatan dan kasih sayang dari Dexter serta para guru, dia sudah menganggap akademi sebagai rumah sejatinya.\n\nKeteguhan, rasionalitas, dan kebaikan yang tepat membuatnya tidak memiliki sifat \"aneh\" sama sekali — dalam kelompok orang aneh di Mythag, \"kebiasaan\" miliknya justru menonjol.\nMeskipun selalu tampak dingin, mereka yang mengenalnya tahu bahwa itu hanya karena kelelahan menjadi seorang \"jenius\"."
  },
  CollectionHall_51375_LockTip = {
    Text = "Setelah \"Ramona\"dibangun, kunci akan terbuka."
  },
