  CollectionHall_57615_Title = {Text = "Thais"},
  CollectionHall_57616_Title = {
    Text = "Di antara bintang-bintang"
  },
  CollectionHall_57617_Desc = {
    Text = "<Title:Ikhtisar>\nGuru psikologi di Universitas Mythag, bertanggung jawab atas bimbingan psikologis para Penyelidik.\nLembut dan baik hati, ia sangat disukai oleh guru dan siswa di dalam kampus, namun beberapa anggota Mythag merasa sangat takut kepadanya.\nBelum lagi teh merah dengan komposisi yang tidak jelas—tak seorang pun pernah melihatnya tanpa senyuman, hanya ini saja sudah cukup membuat orang merinding."
  },
  CollectionHall_57617_LockTip = {
    Text = "Membuka setelah menyelesaikan prolog"
  },
  CollectionHall_57617_Title = {Text = "Sylvia"},
  CollectionHall_57618_Title = {Text = "Pembodoh"},
  CollectionHall_57619_Title = {Text = "Hibrid"},
  CollectionHall_57620_LockTip = {
    Text = "Bangunkan\"Pikman\"untuk membuka kunci"
