  CollectionHall_61045_Title = {
    Text = "A minor: Symphony Terakhir"
  },
  CollectionHall_62183_Title = {
    Text = "08 Symphony Terakhir"
  },
  CollectionHall_62184_Desc = {
    Text = "<Title:Pengantar>\nSeorang maestro dan musisi yang terkenal di seluruh dunia. Meskipun terlihat muda, penampilan orkestra yang dipimpinnya sudah berkeliling ke seluruh dunia, dan setiap pertunjukan selalu menarik banyak penonton.\nSebagai seorang jenius yang paling terkenal di dunia musik klasik, tidak ada informasi pribadi tentang Hameln yang diketahui, yang menarik perhatian Komite. Dalam penyelidikan yang berkepanjangan, mereka menemukan bahwa lokasi pertunjukan Hameln sangat tumpang tindih dengan jejak tindakan Gereja penerang kuil.\nSebelum mereka menemukan kebenaran, kebenaran menemui mereka terlebih dahulu — dalam insiden invasi Mythag oleh Gereja penerang kuil, Hameln memainkan peran yang sangat penting.\nPada saat itu, orang-orang baru menyadari bahwa panggung sebenarnya dari maestro jenius ini selalu ada di luar teater."
  },
  CollectionHall_62184_LockTip = {
    Text = "Bab 8 Operasi Penyelidikan \"Symphony terakhir\" terbuka setelah menyelesaikan"
  },
  CollectionHall_62184_Title = {Text = "Hameln"},
